export type Role = 'client' | 'admin' | 'driver';
export type User = {
  id: string;
  name: string;
  phone: string;
  role: Role;
  active?: boolean;
  photo?: string | null;
};
export type UserCredentials = User & { passwordHash: string };
export type Point = [number, number];
export type Vehicle = {
  id: string;
  name: string;
  volume: string;
  length: string;
  height: string;
  width: string;
  wheelWidth: string;
  image: string;
  interior: string;
  active?: boolean;
  prices: [number, number, number];
};
export type BookingSlot = { label: string; startHour: number };
export type Driver = {
  id: string;
  userId: string | null;
  name: string;
  phone: string;
  photo: string | null;
  active: boolean;
  vehicleId: string | null;
};
export type BookingRules = {
  bookingsEnabled: boolean;
  maxAdvanceDays: number;
  minNoticeHours: number;
  maxOptions: number;
  maxTrips: number;
  clientCancellation: boolean;
  cancellationNoticeHours: number;
  enabledSlots: BookingSlot[];
};
export type Settings = BookingRules & {
  distanceBounds: [number, number, number];
  labourPrice: number;
  assemblyPrice: number;
  businessPhone: string;
  whatsappPhone: string;
  businessName: string;
  businessAddress: string;
  invoiceFooter: string;
  tiktokUrl: string | null;
  facebookUrl: string | null;
  instagramUrl: string | null;
  invoiceLogo: string | null;
  invoiceStamp: string | null;
  invoiceSignature: string | null;
};
export type Catalogue = { vehicles: Vehicle[]; settings: Settings };
export type TollPoint = {
  id: string;
  name: string;
  region: string;
  axis: string;
  heavyPrice: number;
  vehiclePrices: Record<string, number>;
  latitude: number | null;
  longitude: number | null;
};
export type TollPointInput = Omit<TollPoint, 'id'>;
export type Options = { labour: number; desk: number; wardrobe: number; bed: number };
export type PriceLine = { label: string; quantity: number; unitPrice: number; total: number };
export type Price = {
  lines: PriceLine[];
  total: number | null;
  discount: number;
  tier: number;
  trips: number;
  currency: 'XOF';
};
export type Route = {
  from: Point;
  to: Point;
  distanceKm: number;
  durationMinutes: number;
  geometry: Point[];
};
export type RouteTicket = Route & { id: string; expiresAt: string };
export type BookingStatus = 'pending' | 'confirmed' | 'in_progress' | 'completed' | 'cancelled';
export type BookingTrip = {
  id: string;
  sequence: number;
  loadingPhotos: string[];
  unloadingPhotos: string[] | null;
  startedAt: string;
  finishedAt: string | null;
};
export type VehicleInspectionPhotos = {
  engineOil: string;
  coolant: string;
  brakeFluid: string;
  powerSteering: string;
  washerFluid: string;
  condition: string[];
};
export type Quote = {
  id: string;
  reference: string;
  kind: 'provisional' | 'final';
  createdAt: string;
  price: Price;
  notes: string;
  options?: Options;
};
export type Booking = {
  id: string;
  reference: string;
  userId: string;
  driverId?: string | null;
  customerName: string;
  phone: string;
  vehicle: Vehicle;
  fromAddress: string;
  toAddress: string;
  from: Point;
  to: Point;
  distanceKm: number;
  date: string | null;
  timeSlot: string;
  options: Options;
  notes: string;
  status: BookingStatus;
  pricingSettings?: Settings;
  estimate: Price;
  quotes: Quote[];
  trips?: BookingTrip[];
  driverFinishedAt?: string | null;
  createdAt: string;
  version: number;
};
export type BookingInput = {
  vehicleId: string;
  routeId: string;
  customerName: string;
  customerPhone: string;
  fromAddress: string;
  toAddress: string;
  date: string | null;
  timeSlot: string;
  options: Options;
  notes: string;
  requestId: string;
};
export type QuoteInput = {
  kind: 'provisional' | 'final';
  trips: number;
  customPrice: number | null;
  discount: number;
  notes: string;
  extraLines: Array<{ label: string; quantity: number; unitPrice: number }>;
  options?: Options;
  version: number;
};
